import{_ as r,C as s,o as n,c as i,j as d,a,E as o,a2 as c}from"./chunks/framework.BxGh02fV.js";const _=JSON.parse('{"title":"Development standards","description":"","frontmatter":{"title":"Development standards"},"headers":[],"relativePath":"en/agent/normes.md","filePath":"en/agent/normes.md"}'),l={name:"en/agent/normes.md"};function h(f,e,m,p,u,g){const t=s("Ask");return n(),i("div",null,[e[0]||(e[0]=d("h1",{id:"development-standards",tabindex:"-1"},[a("Development standards "),d("a",{class:"header-anchor",href:"#development-standards","aria-label":'Permalink to "Development standards"'},"​")],-1)),e[1]||(e[1]=d("p",null,`Development standards (NDD) are your project's code rules: one family per language, each rule with its level and its "why". You come to this path so the agent knows which rules apply to a task, to fetch the standards of a shared repository, or to evolve a rule.`,-1)),e[2]||(e[2]=d("h2",{id:"what-you-ask-the-agent",tabindex:"-1"},[a("What you ask the agent "),d("a",{class:"header-anchor",href:"#what-you-ask-the-agent","aria-label":'Permalink to "What you ask the agent"'},"​")],-1)),o(t,{say:"Which standards apply to the task you are about to do in codebase/api/?",verb:"effortless_ndd_resolve",family:"normes",args:'{"path":"codebase/api/"}'}),o(t,{say:"List all the Rust rules, with their text.",verb:"effortless_ndd_resolve",family:"normes",args:'{"include_body":true}'}),o(t,{say:"Import the Rust standard of the api module from my standards repository.",verb:"effortless_ndd_import",family:"normes",args:'{"stack_id":"api","techno":"rust"}'}),o(t,{say:"Use this standards repository for all my projects: git@example.org:me/standards.git.",verb:"effortless_ndd_source",family:"normes",args:'{"source":"git@example.org:me/standards.git"}'}),o(t,{say:"Update this project's standards from the shared repository.",verb:"effortless_ndd_sync",family:"normes"}),o(t,{say:'Propose making rule RUST-12 of the rust standard mandatory, because swallowed errors cost us a lot: "Propagate errors — every error is propagated or logged."',verb:"effortless_ndd_amendment_propose",family:"normes",args:'{"family":"rust","target_id":"RUST-12","proposed_id":"RUST-12","level":"OBLIGATOIRE","title":"Propagate errors","why":"Swallowed errors cost us a lot","body":"Every error is propagated or logged."}'}),o(t,{say:"I accept the amendment AMD-03 you just proposed.",verb:"effortless_ndd_amendment_accept",family:"normes",args:'{"proposal_id":"AMD-03"}'}),o(t,{say:"Reject amendment AMD-03: we do not want this rule for now.",verb:"effortless_ndd_amendment_reject",family:"normes",args:'{"proposal_id":"AMD-03","reason":"We do not want this rule for now"}'}),e[3]||(e[3]=c('<h2 id="what-the-agent-does" tabindex="-1">What the agent does <a class="header-anchor" href="#what-the-agent-does" aria-label="Permalink to &quot;What the agent does&quot;">​</a></h2><h3 id="find-out-which-standards-apply" tabindex="-1">Find out which standards apply <a class="header-anchor" href="#find-out-which-standards-apply" aria-label="Permalink to &quot;Find out which standards apply&quot;">​</a></h3><ol><li><a href="/Effortless/en/reference/mcp/normes.html#ndd-resolve"><code>effortless_ndd_resolve</code></a>: read-only. The agent passes <code>stack</code> (the families to resolve, named like the folders of <code>.ai/ndd/</code>) or <code>path</code> (a project path from which it derives the families). With neither, it gets the whole known corpus.</li><li>Each rule comes back qualified: identifier, level (<code>OBLIGATOIRE</code>, <code>RECOMMANDÉ</code> or <code>INTERDIT</code>), title, why, family, origin, file and line. The full text is served only if the agent passes <code>include_body: true</code>.</li></ol><h3 id="import-a-standard-from-a-shared-repository" tabindex="-1">Import a standard from a shared repository <a class="header-anchor" href="#import-a-standard-from-a-shared-repository" aria-label="Permalink to &quot;Import a standard from a shared repository&quot;">​</a></h3><ol><li>The address of the standard is declared in the stack, under <code>languages[].ndd.source</code>. If it is missing or must change, the agent fixes it with <a href="/Effortless/en/reference/mcp/stacks.html#stack-declare-languages"><code>effortless_stack_declare_languages</code></a> (see <a href="/Effortless/en/agent/code.html">Code and stacks</a>).</li><li><a href="/Effortless/en/reference/mcp/normes.html#ndd-import"><code>effortless_ndd_import</code></a> with <code>stack_id</code> and <code>techno</code> (the language, which also gives the family name). The verb reads the file from the repository with <code>git show</code>, without cloning or fetching the repository, and writes the inherited standard to <code>.ai/ndd/&lt;family&gt;/&lt;family&gt;-ndd.v1.heritee.md</code>, with a provenance file (repository, reference, date).</li><li>If the git reference cannot be found, the import breaks nothing: the response carries <code>available: false</code> with the reason, and no file is written.</li></ol><h3 id="follow-a-shared-standards-repository" tabindex="-1">Follow a shared standards repository <a class="header-anchor" href="#follow-a-shared-standards-repository" aria-label="Permalink to &quot;Follow a shared standards repository&quot;">​</a></h3><ol><li><a href="/Effortless/en/reference/mcp/normes.html#ndd-source"><code>effortless_ndd_source</code></a> declares the global source: a local folder or a git URL, with <code>reference</code> for a branch or tag. Without <code>source</code>, it reads the current source; with an empty string, it removes it. A project can override it with <code>settings.ndd_source</code> in its <code>effortless.json</code>.</li><li><a href="/Effortless/en/reference/mcp/normes.html#ndd-sync"><code>effortless_ndd_sync</code></a> updates the project&#39;s inherited standards for each language present (declared stacks, families already there, and the <code>agnostic</code> family). It returns the families updated, unchanged, and those the repository does not carry. It never touches the local standard.</li></ol><h3 id="propose-accept-or-reject-an-amendment" tabindex="-1">Propose, accept or reject an amendment <a class="header-anchor" href="#propose-accept-or-reject-an-amendment" aria-label="Permalink to &quot;Propose, accept or reject an amendment&quot;">​</a></h3><ol><li><a href="/Effortless/en/reference/mcp/normes.html#ndd-amendment-propose"><code>effortless_ndd_amendment_propose</code></a> with <code>family</code>, <code>proposed_id</code>, <code>level</code>, <code>title</code>, <code>why</code>, <code>body</code>, and <code>target_id</code> if the amendment changes an existing rule (absent: new rule). The text is analyzed the way <code>effortless_ndd_resolve</code> does. Only the <code>.effortless/ndd_amendments.json</code> registry is written (status Proposed); no standard file is touched.</li><li><a href="/Effortless/en/reference/mcp/normes.html#ndd-amendment-accept"><code>effortless_ndd_amendment_accept</code></a> with <code>proposal_id</code>. The content is always written on the <strong>local</strong> side (<code>.ai/ndd/&lt;family&gt;/&lt;family&gt;-ndd.v1.md</code>), never in an inherited file: amending an inherited rule means overriding it locally. Same identifier as the target: the section is edited in place. Different identifier: a new section is added, the old one is not touched.</li><li><a href="/Effortless/en/reference/mcp/normes.html#ndd-amendment-reject"><code>effortless_ndd_amendment_reject</code></a> with <code>proposal_id</code> and <code>reason</code>. The reason is recorded word for word with the date; no standard file is opened for writing.</li></ol><p>The agent never accepts or rejects an amendment on its own: the decision is yours, and it carries it out after your agreement.</p><h2 id="what-you-get" tabindex="-1">What you get <a class="header-anchor" href="#what-you-get" aria-label="Permalink to &quot;What you get&quot;">​</a></h2><ul><li>A clear list of rules before the work, instead of a guessed standard.</li><li>In the project: files under <code>.ai/ndd/</code> (local and inherited standards, plus the provenance of the inherited ones) and the <code>.effortless/ndd_amendments.json</code> registry.</li><li>In the app: the address of the shared repository is set in <strong>Preferences</strong> › <strong>Standards</strong> (see <a href="/Effortless/en/guide/preferences.html">Profile and preferences</a>), and the <a href="/Effortless/en/guide/modules.html">Modules</a> screen shows the <strong>Standards</strong> present for each module.</li></ul><h2 id="when-the-agent-is-refused" tabindex="-1">When the agent is refused <a class="header-anchor" href="#when-the-agent-is-refused" aria-label="Permalink to &quot;When the agent is refused&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Situation</th><th>What the refusal says</th><th>What to do</th></tr></thead><tbody><tr><td>No standard in the project</td><td><code>ndd:aucuneNorme</code></td><td>Import or sync a standard (<code>effortless_ndd_import</code>, <code>effortless_ndd_sync</code>).</td></tr><tr><td>Requested family unknown</td><td><code>ndd:familleInconnue</code> (the response lists the available families)</td><td>Pick <code>stack</code> or <code>family</code> among the listed families.</td></tr><tr><td>Rule level out of the standard</td><td><code>ndd:niveauInconnu</code> (file and line named)</td><td>Fix the line: the level must be OBLIGATOIRE, RECOMMANDÉ or INTERDIT.</td></tr><tr><td>Rule without a &quot;Why&quot;</td><td><code>ndd:pourquoiAbsent</code></td><td>Add the &quot;<strong>Pourquoi</strong> :&quot; line to the named rule, or pass <code>why</code> to a proposal.</td></tr><tr><td>Two rules with the same identifier</td><td><code>ndd:identifiantEnDouble</code> (both locations named)</td><td>Rename one of the two identifiers.</td></tr><tr><td>Unknown stack on import</td><td><code>ndd:stackInconnue</code></td><td>List the stacks with <code>effortless_stack_list</code>.</td></tr><tr><td>Language missing from the stack</td><td><code>ndd:languageInconnu</code></td><td>Declare the languages with <code>effortless_stack_declare_languages</code>.</td></tr><tr><td>Standard source is not git</td><td><code>ndd:sourceNonGit</code></td><td>Declare the source as <code>git</code> for this language; the import accepts only that.</td></tr><tr><td>Standards source not found or unreachable</td><td><code>ndd:sourceIntrouvable</code>, <code>ndd:sourceInjoignable</code></td><td>Fix the address with <code>effortless_ndd_source</code> (existing folder or git URL) and check your git access.</td></tr><tr><td>Corporate certificate not recognized by git</td><td><code>ndd:certificatNonReconnu</code></td><td>Install the company root certificate, or declare it to git, then run <code>effortless_ndd_sync</code> again.</td></tr><tr><td>Amendment: targeted identifier not found</td><td><code>ndd:identifiantViseInconnu</code></td><td>Look the identifier up with <code>effortless_ndd_resolve</code>.</td></tr><tr><td>Amendment: unknown proposal</td><td><code>ndd:propositionInconnue</code></td><td>Use the identifier returned by <code>effortless_ndd_amendment_propose</code>.</td></tr><tr><td>Amendment: already accepted or rejected</td><td><code>ndd:amendementDejaArbitre</code></td><td>No action reopens it; a new proposal opens a new amendment.</td></tr><tr><td>Rejection without a reason</td><td><code>ndd:amendementRejectReasonRequired</code></td><td>Give <code>reason</code>.</td></tr></tbody></table>',14))])}const w=r(l,[["render",h]]);export{_ as __pageData,w as default};
